parameters.jsCode:
const items = $input.all();

if (items.length !== 1) {
  throw new Error(
    `M5_02_EXPECTED_ONE_ITEM: Se esperaba un elemento y se recibieron ${items.length}.`
  );
}

const raw = items[0]?.json ?? {};

function isPlainObject(value) {
  return (
    value !== null &&
    typeof value === 'object' &&
    !Array.isArray(value)
  );
}

function objectOrEmpty(value) {
  return isPlainObject(value) ? value : {};
}

function arrayOrEmpty(value) {
  return Array.isArray(value) ? value : [];
}

function nullableString(value) {
  if (typeof value !== 'string') {
    return value ?? null;
  }

  const normalized = value.trim();
  return normalized.length > 0 ? normalized : null;
}

function normalizeNumber(value) {
  if (value === null || value === undefined || value === '') {
    return null;
  }

  const number = Number(value);
  return Number.isFinite(number) ? number : null;
}

const operation = objectOrEmpty(raw.operation);
const transaction = objectOrEmpty(raw.transaction);
const customer = objectOrEmpty(raw.customer);
const paymentContext = objectOrEmpty(raw.payment_context);
const configuration = objectOrEmpty(raw.configuration);
const requestContext = objectOrEmpty(raw.request_context);
const trace = objectOrEmpty(raw.trace);

return [
  {
    json: {
      operation: {
        action: nullableString(operation.action)?.toLowerCase() ?? null,
        requested_at: nullableString(operation.requested_at) ?? new Date().toISOString(),
        idempotency_key: nullableString(operation.idempotency_key)
      },

      transaction: {
        ...transaction,
        id: nullableString(transaction.id),
        business_id: nullableString(transaction.business_id),
        customer_id: nullableString(transaction.customer_id),
        status: nullableString(transaction.status)?.toLowerCase() ?? null,
        sub_status: nullableString(transaction.sub_status)?.toLowerCase() ?? null,
        next_action: nullableString(transaction.next_action)?.toLowerCase() ?? null,
        currency: nullableString(transaction.currency)?.toUpperCase() ?? 'COP',
        total: normalizeNumber(transaction.total),
        metadata: objectOrEmpty(transaction.metadata)
      },

      items: arrayOrEmpty(raw.items).map((item) => {
        const clean = objectOrEmpty(item);

        return {
          ...clean,
          sku: nullableString(clean.sku),
          name: nullableString(clean.name),
          quantity: normalizeNumber(clean.quantity),
          unit_price: normalizeNumber(clean.unit_price),
          total: normalizeNumber(clean.total),
          metadata: objectOrEmpty(clean.metadata)
        };
      }),

      customer: {
        ...customer,
        customer_id: nullableString(customer.customer_id),
        name: nullableString(customer.name),
        phone: nullableString(customer.phone),
        email: nullableString(customer.email)?.toLowerCase() ?? null
      },

      payment_context: {
        ...paymentContext,
        amount: normalizeNumber(paymentContext.amount),
        currency: nullableString(paymentContext.currency)?.toUpperCase() ?? null,
        existing_payment: paymentContext.existing_payment ?? null,
        customer_confirmation: objectOrEmpty(paymentContext.customer_confirmation)
      },

      configuration: {
        payment: objectOrEmpty(configuration.payment),
        automation: objectOrEmpty(configuration.automation)
      },

      dependencies: objectOrEmpty(raw.dependencies),

      external_event:
        raw.external_event === null || raw.external_event === undefined
          ? null
          : objectOrEmpty(raw.external_event),

      request_context: {
        ...requestContext,
        business_id: nullableString(requestContext.business_id),
        session_id: nullableString(requestContext.session_id),
        channel: nullableString(requestContext.channel)?.toLowerCase() ?? null,
        source_module: nullableString(requestContext.source_module)
      },

      orchestration_route: objectOrEmpty(raw.orchestration_route),

      trace: {
        ...trace,
        trace_id: nullableString(trace.trace_id),
        request_id: nullableString(trace.request_id),
        parent_workflow: nullableString(trace.parent_workflow)
      },

      payment_execution: {
        workflow: 'DALIA_M5_02_Payment_Management',
        received_at: new Date().toISOString(),
        stage: 'input_normalized'
      }
    }
  }
];

const payload = $input.first().json;

const missingFields = [];
const invalidFields = [];

function isNonEmptyString(value) {
  return typeof value === 'string' && value.trim().length > 0;
}

function isPositiveNumber(value) {
  return typeof value === 'number' && Number.isFinite(value) && value > 0;
}

function requireString(value, field) {
  if (!isNonEmptyString(value)) {
    missingFields.push(field);
  }
}

function invalid(field, reason, value = undefined) {
  const item = { field, reason };

  if (value !== undefined) {
    item.value = value;
  }

  invalidFields.push(item);
}

const allowedActions = new Set([
  'create_payment',
  'process_payment_event'
]);

requireString(payload.operation?.action, 'operation.action');
requireString(payload.operation?.idempotency_key, 'operation.idempotency_key');
requireString(payload.transaction?.id, 'transaction.id');
requireString(payload.transaction?.business_id, 'transaction.business_id');
requireString(payload.transaction?.status, 'transaction.status');
requireString(payload.request_context?.business_id, 'request_context.business_id');
requireString(payload.trace?.trace_id, 'trace.trace_id');
requireString(payload.trace?.request_id, 'trace.request_id');

if (
  isNonEmptyString(payload.operation?.action) &&
  !allowedActions.has(payload.operation.action)
) {
  invalid('operation.action', 'unsupported_action', payload.operation.action);
}

const uuidPattern =
  /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;

if (
  isNonEmptyString(payload.transaction?.id) &&
  !uuidPattern.test(payload.transaction.id)
) {
  invalid('transaction.id', 'invalid_uuid', payload.transaction.id);
}

if (
  payload.transaction?.business_id &&
  payload.request_context?.business_id &&
  payload.transaction.business_id !== payload.request_context.business_id
) {
  invalid(
    'request_context.business_id',
    'business_id_mismatch',
    {
      transaction_business_id: payload.transaction.business_id,
      request_business_id: payload.request_context.business_id
    }
  );
}

const payment = payload.configuration?.payment ?? {};

if (payment.required !== true) {
  invalid(
    'configuration.payment.required',
    'payment_workflow_called_when_payment_not_required',
    payment.required
  );
}

if (payment.mode !== 'online') {
  invalid(
    'configuration.payment.mode',
    'shopify_checkout_requires_online_payment_mode',
    payment.mode
  );
}

if (payment.provider !== 'shopify') {
  invalid(
    'configuration.payment.provider',
    'provider_must_be_shopify',
    payment.provider
  );
}

if (
  !Array.isArray(payment.allowed_methods) ||
  !payment.allowed_methods.includes('shopify_checkout')
) {
  invalid(
    'configuration.payment.allowed_methods',
    'shopify_checkout_method_required',
    payment.allowed_methods
  );
}

if (
  payload.operation?.action === 'create_payment' &&
  !isPositiveNumber(payload.payment_context?.amount)
) {
  invalid(
    'payment_context.amount',
    'must_be_positive_number',
    payload.payment_context?.amount
  );
}

if (
  payload.operation?.action === 'create_payment' &&
  (!Array.isArray(payload.items) || payload.items.length === 0)
) {
  missingFields.push('items');
}

if (
  payload.operation?.action === 'create_payment' &&
  Array.isArray(payload.items)
) {
  payload.items.forEach((item, index) => {
    if (!isNonEmptyString(item.sku)) {
      missingFields.push(`items[${index}].sku`);
    }

    if (!isPositiveNumber(item.quantity)) {
      invalid(
        `items[${index}].quantity`,
        'must_be_positive_number',
        item.quantity
      );
    }
  });
}

if (
  payload.operation?.action === 'process_payment_event' &&
  !payload.external_event
) {
  missingFields.push('external_event');
}

const uniqueMissing = [...new Set(missingFields)];

const uniqueInvalid = Array.from(
  new Map(
    invalidFields.map((item) => [
      `${item.field}:${item.reason}`,
      item
    ])
  ).values()
);

return [
  {
    json: {
      ...payload,
      internal_contract_validation: {
        valid: uniqueMissing.length === 0 && uniqueInvalid.length === 0,
        missing_fields: uniqueMissing,
        invalid_fields: uniqueInvalid,
        validated_at: new Date().toISOString()
      },
      payment_execution: {
        ...(payload.payment_execution ?? {}),
        stage: 'internal_contract_validated'
      }
    }
  }
];

const payload = $input.first().json;
const validation = payload.internal_contract_validation ?? {};

return [
  {
    json: {
      result: {
        success: false,
        outcome: 'transaction_failed'
      },

      transaction: {
        transaction_id: payload.transaction?.id ?? null,
        previous_status: payload.transaction?.status ?? null,
        current_status: payload.transaction?.status ?? null,
        sub_status: payload.transaction?.sub_status ?? null,
        next_action: payload.transaction?.next_action ?? null
      },

      route: {
        selected_flow: 'DALIA_M5_02_Payment_Management',
        effective_action: payload.operation?.action ?? null,
        reason: 'invalid_internal_contract'
      },

      response: {
        message_required: false,
        message_type: null,
        reply_text: null,
        requested_fields: []
      },

      data: {
        internal_contract_validation: validation
      },

      error: {
        code: 'INVALID_M5_02_INPUT',
        category: 'validation',
        message: 'La entrada interna de gestión de pago con Shopify no es válida.',
        retryable: false,
        details: {
          missing_fields: validation.missing_fields ?? [],
          invalid_fields: validation.invalid_fields ?? []
        }
      },

      trace: {
        trace_id: payload.trace?.trace_id ?? null,
        request_id: payload.trace?.request_id ?? null,
        workflow: 'DALIA_M5_02_Payment_Management',
        stage: 'input_rejected',
        processed_at: new Date().toISOString()
      }
    }
  }
];

const databaseResult = $input.first().json;

const workflowInput = databaseResult.workflow_input ?? {};
const currentTransaction = databaseResult.current_transaction ?? null;
const latestPayment = databaseResult.latest_payment ?? null;

const action = workflowInput.operation?.action;
const errors = [];

if (databaseResult.transaction_found !== true) {
  errors.push({
    code: 'TRANSACTION_NOT_FOUND',
    reason: 'transaction_not_found_or_not_accessible'
  });
}

if (currentTransaction) {
  if (action === 'create_payment') {
    if (currentTransaction.status !== 'commercially_validated') {
      errors.push({
        code: 'INVALID_SHOPIFY_CHECKOUT_CREATION_STATUS',
        reason: 'shopify_checkout_can_only_be_created_from_commercially_validated',
        current_status: currentTransaction.status
      });
    }

    if (currentTransaction.next_action !== 'create_payment') {
      errors.push({
        code: 'INVALID_NEXT_ACTION',
        reason: 'next_action_must_be_create_payment',
        current_next_action: currentTransaction.next_action
      });
    }
  }

  if (action === 'process_payment_event') {
    if (currentTransaction.status !== 'payment_pending') {
      errors.push({
        code: 'INVALID_SHOPIFY_PAYMENT_EVENT_STATUS',
        reason: 'shopify_payment_events_can_only_be_processed_from_payment_pending',
        current_status: currentTransaction.status
      });
    }

    if (
      currentTransaction.next_action !== 'wait_payment_confirmation' &&
      currentTransaction.next_action !== 'process_payment_event'
    ) {
      errors.push({
        code: 'INVALID_NEXT_ACTION',
        reason: 'next_action_must_wait_for_payment_confirmation',
        current_next_action: currentTransaction.next_action
      });
    }
  }
}

return [
  {
    json: {
      ...workflowInput,

      current_transaction: currentTransaction,
      latest_payment: latestPayment,

      transaction_recheck: {
        valid: errors.length === 0,
        errors,
        checked_at: new Date().toISOString()
      },

      payment_execution: {
        ...(workflowInput.payment_execution ?? {}),
        stage: 'transaction_rechecked'
      }
    }
  }
];

const payload = $input.first().json;

const transaction =
  payload.current_transaction ??
  payload.transaction ??
  {};

const recheck = payload.transaction_recheck ?? {};
const mainError = recheck.errors?.[0] ?? {};

return [
  {
    json: {
      result: {
        success: false,
        outcome: 'transaction_failed'
      },

      transaction: {
        transaction_id: transaction.id ?? null,
        previous_status: payload.transaction?.status ?? null,
        current_status: transaction.status ?? null,
        sub_status: transaction.sub_status ?? null,
        next_action: transaction.next_action ?? null
      },

      route: {
        selected_flow: 'DALIA_M5_02_Payment_Management',
        effective_action: payload.operation?.action ?? null,
        reason: mainError.reason ?? 'transaction_recheck_failed'
      },

      response: {
        message_required: false,
        message_type: null,
        reply_text: null,
        requested_fields: []
      },

      data: {
        transaction_recheck: recheck
      },

      error: {
        code: mainError.code ?? 'TRANSACTION_RECHECK_FAILED',
        category: 'business_rule',
        message: 'La transacción no está en un estado válido para gestionar checkout de Shopify.',
        retryable: false,
        details: {
          errors: recheck.errors ?? []
        }
      },

      trace: {
        trace_id: payload.trace?.trace_id ?? null,
        request_id: payload.trace?.request_id ?? null,
        workflow: 'DALIA_M5_02_Payment_Management',
        stage: 'transaction_recheck_failed',
        processed_at: new Date().toISOString()
      }
    }
  }
];

const result = $input.first().json;

const payload = result.workflow_payload ?? {};
const transaction =
  result.transaction ??
  payload.current_transaction ??
  {};

const payment =
  result.payment ??
  payload.latest_payment ??
  null;

const action = payload.operation?.action;

let outcome = 'action_completed';
let success = true;
let messageRequired = false;
let messageType = null;
let replyText = null;
let error = null;

if (action === 'create_payment') {
  outcome = 'waiting_external_event';
  messageRequired = true;
  messageType = 'send_shopify_checkout_url';

  const customerName =
    payload.customer?.name?.split(' ')?.[0] ??
    '';

  const itemsText =
    (payload.items ?? [])
      .map((item) => {
        const variant =
          item.metadata?.variant
            ? ` ${item.metadata.variant}`
            : '';

        return `${item.quantity}x ${item.name}${variant}`;
      })
      .join(', ');

  const checkoutUrl =
    payment?.payment_url ??
    payload.shopify_cart_result?.checkout_url ??
    null;

  replyText = checkoutUrl
    ? `¡Perfecto${customerName ? `, ${customerName}` : ''}! Para finalizar tu compra de ${itemsText}, ingresa a este link seguro de Shopify: ${checkoutUrl}`
    : 'Tu carrito fue creado en Shopify. Te compartiremos el enlace para finalizar la compra.';
}

if (action === 'process_payment_event') {
  const status =
    payload.normalized_shopify_event?.normalized_status;

  if (status === 'confirmed') {
    outcome = 'action_completed';
    messageRequired = false;
  } else if (status === 'failed') {
    outcome = 'action_pending';
    messageRequired = true;
    messageType = 'shopify_payment_failed';
    replyText = 'El pago no pudo ser confirmado en Shopify. Puedes intentar nuevamente desde el enlace de compra.';
  } else if (status === 'expired') {
    outcome = 'transaction_failed';
    success = false;
    error = {
      code: 'SHOPIFY_CHECKOUT_EXPIRED',
      category: 'business_rule',
      message: 'El checkout de Shopify expiró.',
      retryable: false,
      details: {}
    };
  } else {
    outcome = 'waiting_external_event';
  }
}

return [
  {
    json: {
      result: {
        success,
        outcome
      },

      transaction: {
        transaction_id: transaction.id ?? null,
        previous_status: payload.current_transaction?.status ?? null,
        current_status: transaction.status ?? null,
        sub_status: transaction.sub_status ?? null,
        next_action: transaction.next_action ?? null
      },

      route: {
        selected_flow: 'DALIA_M5_02_Payment_Management',
        effective_action: action ?? null,
        reason:
          action === 'create_payment'
            ? 'shopify_checkout_created'
            : 'shopify_payment_event_processed'
      },

      response: {
        message_required: messageRequired,
        message_type: messageType,
        reply_text: replyText,
        requested_fields: []
      },

      data: {
        payment: {
          payment_id: payment?.id ?? null,
          provider: 'shopify',
          provider_payment_id: payment?.provider_payment_id ?? null,
          payment_method: 'shopify_checkout',
          status: payment?.status ?? null,
          amount: payment?.amount ?? null,
          currency: payment?.currency ?? null,
          payment_url: payment?.payment_url ?? null,
          expires_at: payment?.expires_at ?? null,
          duplicate: result.duplicate === true || result.duplicate_or_existing === true,
          shopify_cart_id:
            payment?.metadata?.shopify_cart_id ??
            payload.shopify_cart_result?.cart?.id ??
            null,
          shopify_checkout_url:
            payment?.metadata?.shopify_checkout_url ??
            payment?.payment_url ??
            payload.shopify_cart_result?.checkout_url ??
            null,
          shopify_order_id:
            payment?.metadata?.shopify_order_id ??
            payload.normalized_shopify_event?.shopify_order_id ??
            null
        },

        shopify: {
          cart_result:
            payload.shopify_cart_result ?? null,
          cart_lines:
            payload.shopify_cart_lines ?? null,
          webhook:
            payload.normalized_shopify_event ?? null
        },

        event_id: result.event_id ?? null
      },

      error,

      trace: {
        trace_id: payload.trace?.trace_id ?? null,
        request_id: payload.trace?.request_id ?? null,
        workflow: 'DALIA_M5_02_Payment_Management',
        execution_id:
          typeof $execution !== 'undefined'
            ? $execution.id
            : null,
        stage: 'shopify_payment_operation_completed',
        processed_at: new Date().toISOString()
      }
    }
  }
];

const payload = $input.first().json;

const latestPayment = payload.latest_payment ?? null;

let decision = 'create_new_shopify_cart';
let reason = 'no_existing_shopify_checkout';

if (latestPayment) {
  const isShopify =
    latestPayment.provider === 'shopify' ||
    latestPayment.payment_method === 'shopify_checkout';

  if (
    isShopify &&
    ['pending', 'created', 'waiting_confirmation'].includes(latestPayment.status)
  ) {
    decision = 'return_existing_shopify_checkout';
    reason = 'pending_shopify_checkout_already_exists';
  }

  if (
    isShopify &&
    latestPayment.status === 'confirmed'
  ) {
    decision = 'shopify_payment_already_confirmed';
    reason = 'confirmed_shopify_payment_already_exists';
  }
}

return [
  {
    json: {
      ...payload,
      shopify_checkout_decision: {
        decision,
        reason,
        evaluated_at: new Date().toISOString()
      }
    }
  }
];

const payload = $input.first().json;

const skus = [];

for (const item of payload.items ?? []) {
  if (item.sku) {
    skus.push(item.sku);
  }
}

const uniqueSkus = [...new Set(skus)];

const queryString = uniqueSkus
  .map((sku) => `sku:${sku}`)
  .join(' OR ');

return [
  {
    json: {
      ...payload,

      shopify_product_query: {
        query: queryString,
        skus: uniqueSkus,
        built_at: new Date().toISOString()
      }
    }
  }
];

