query GetProductsForCart($query: String!) {
  products(first: 20, query: $query) {
    edges {
      node {
        id
        title
        handle
        variants(first: 20) {
          edges {
            node {
              id
              title
              sku
              availableForSale
              price {
                amount
                currencyCode
              }
            }
          }
        }
      }
    }
  }
}

parameters.jsCode:
const shopifyResponse = $input.first().json;

const payload =
  shopifyResponse.workflow_payload ??
  $('09A_Build_Shopify_Product_Query').first().json;

const products =
  shopifyResponse.data?.products?.edges ?? [];

const variantsBySku = {};

for (const productEdge of products) {
  const product = productEdge.node;

  for (const variantEdge of product.variants.edges ?? []) {
    const variant = variantEdge.node;

    if (variant.sku) {
      variantsBySku[variant.sku] = {
        ...variant,
        product: {
          id: product.id,
          title: product.title,
          handle: product.handle
        }
      };
    }
  }
}

const lines = [];
const notFound = [];
const notAvailable = [];
const priceWarnings = [];

for (const item of payload.items ?? []) {
  const variant = variantsBySku[item.sku];

  if (!variant) {
    notFound.push({
      sku: item.sku,
      reason: 'sku_not_found_in_shopify'
    });
    continue;
  }

  if (variant.availableForSale !== true) {
    notAvailable.push({
      sku: item.sku,
      reason: 'variant_not_available_for_sale'
    });
    continue;
  }

  const shopifyPrice = Number(variant.price?.amount);
  const expectedPrice = Number(item.unit_price);

  if (
    Number.isFinite(shopifyPrice) &&
    Number.isFinite(expectedPrice) &&
    shopifyPrice !== expectedPrice
  ) {
    priceWarnings.push({
      sku: item.sku,
      expected_price: expectedPrice,
      shopify_price: shopifyPrice,
      currency: variant.price?.currencyCode ?? null
    });
  }

  lines.push({
    merchandiseId: variant.id,
