const shopifyResponse = $input.first().json;

const payload =
  $('11A_Build_Cart_Lines').first().json;

const cartCreate =
  shopifyResponse.data?.cartCreate ?? null;

const errors = [];

if (!cartCreate) {
  errors.push({
    code: 'SHOPIFY_CART_CREATE_EMPTY_RESPONSE',
    message: 'Shopify no devolvió respuesta de cartCreate.'
  });
}

if (cartCreate?.userErrors?.length > 0) {
  errors.push({
    code: 'SHOPIFY_CART_CREATE_USER_ERRORS',
    message: 'Shopify devolvió errores al crear el carrito.',
    user_errors: cartCreate.userErrors
  });
}

if (!cartCreate?.cart?.checkoutUrl) {
  errors.push({
    code: 'SHOPIFY_CHECKOUT_URL_MISSING',
    message: 'Shopify no devolvió checkoutUrl.'
  });
}

const expirationMinutes =
  payload.configuration?.payment?.expiration_minutes ?? null;

const expiresAt =
  Number.isInteger(expirationMinutes)
    ? new Date(Date.now() + expirationMinutes * 60000).toISOString()
    : null;

return [
  {
    json: {
      ...payload,

      shopify_cart_result: {
        valid: errors.length === 0,
        errors,
        cart: cartCreate?.cart ?? null,
        checkout_url: cartCreate?.cart?.checkoutUrl ?? null,
        total_quantity: cartCreate?.cart?.totalQuantity ?? null,
        expires_at: expiresAt,
        normalized_at: new Date().toISOString()
      }
    }
  }
];

const payload = $input.first().json;

return [
  {
    json: {
      result: {
        success: false,
        outcome: 'transaction_failed'
      },

      transaction: {
        transaction_id: payload.current_transaction?.id ?? null,
        previous_status: payload.current_transaction?.status ?? null,
        current_status: payload.current_transaction?.status ?? null,
        sub_status: payload.current_transaction?.sub_status ?? null,
        next_action: payload.current_transaction?.next_action ?? null
      },

      route: {
        selected_flow: 'DALIA_M5_02_Payment_Management',
        effective_action: 'create_payment',
        reason: 'shopify_cart_create_failed'
      },

      response: {
        message_required: false,
        message_type: null,
        reply_text: null,
        requested_fields: []
      },

      data: {
        shopify_cart_result: payload.shopify_cart_result
      },

      error: {
        code: 'SHOPIFY_CART_CREATE_FAILED',
        category: 'external_system',
        message: 'No fue posible crear el carrito de Shopify.',
        retryable: true,
        details: {
          errors: payload.shopify_cart_result?.errors ?? []
        }
      },

      trace: {
        trace_id: payload.trace?.trace_id ?? null,
        request_id: payload.trace?.request_id ?? null,
        workflow: 'DALIA_M5_02_Payment_Management',
        stage: 'shopify_cart_create_failed',
        processed_at: new Date().toISOString()
      }
    }
  }
];

const payload = $input.first().json;

const event = payload.external_event ?? {};

function text(value) {
  if (typeof value !== 'string') {
    return value ?? null;
  }

  const trimmed = value.trim();
  return trimmed.length > 0 ? trimmed : null;
}

const topic = text(event.topic) ?? text(event.event_type);
const financialStatus =
  text(event.financial_status) ??
  text(event.payment_status) ??
  text(event.status);

let normalizedStatus = 'unknown';

if (
  topic === 'orders/paid' ||
  financialStatus === 'paid' ||
  financialStatus === 'authorized' ||
  financialStatus === 'partially_paid'
) {
  normalizedStatus = 'confirmed';
}

if (
  financialStatus === 'voided' ||
  financialStatus === 'refunded' ||
  financialStatus === 'partially_refunded'
) {
  normalizedStatus = 'failed';
}

if (
  topic === 'checkouts/delete' ||
  financialStatus === 'expired'
) {
  normalizedStatus = 'expired';
}

const eventId =
  text(event.event_id) ??
  text(event.webhook_id) ??
  text(event.id) ??
  `${topic}:${event.shopify_order_id ?? event.shopify_cart_id ?? Date.now()}`;

return [
  {
    json: {
      ...payload,

      normalized_shopify_event: {
        provider: 'shopify',
        topic,
        normalized_status: normalizedStatus,
        financial_status: financialStatus ?? null,
        shopify_order_id:
          text(event.shopify_order_id) ??
          text(event.order_id) ??
          null,
        shopify_cart_id:
          text(event.shopify_cart_id) ??
          text(event.cart_id) ??
          null,
        shopify_checkout_id:
          text(event.shopify_checkout_id) ??
          text(event.checkout_id) ??
          null,
        amount:
          Number(
            event.total_price ??
            event.amount ??
            payload.current_transaction?.total
          ),
        currency:
          text(event.currency)?.toUpperCase() ??
          payload.current_transaction?.currency ??
          'COP',
        event_id: eventId,
        transaction_id:
          text(event.transaction_id) ??
          text(event.dalia_transaction_id) ??
          payload.current_transaction?.id ??
          null,
        raw_event: event.raw ?? event,
        received_at: new Date().toISOString()
      }
    }
  }
];
